  const baseRpm = Number(tel.rpm) || 980;
  const baseYieldMhr = Number(tel.fabricOutputMhr) || 98.4;
  const rpmRatio = targetRpm / (baseRpm || 1);
  const pressureRatio = jetPressure / (Number(tel.airPressureBar) || 4.8 || 1);
  const fanCoolingFactor = coolingFanPct / 85;

  // Temperature simulation taking ambient heat + fan cooling into account
  const simTemp = (
    Number(tel.temperature) +
    (targetRpm - baseRpm) * 0.04 +
    (ambientTemp - 32) * 0.4 -
